import{_ as t,o as d,c as r,a0 as o}from"./chunks/framework.BGyYNsHo.js";const l=JSON.parse('{"title":"Scripts, Benchmarks & Verification","description":"","frontmatter":{},"headers":[],"relativePath":"reference/07-scripts-and-benchmarks.md","filePath":"reference/07-scripts-and-benchmarks.md"}'),s={name:"reference/07-scripts-and-benchmarks.md"};function n(a,e,i,c,h,m){return d(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="scripts-benchmarks-verification" tabindex="-1">Scripts, Benchmarks &amp; Verification <a class="header-anchor" href="#scripts-benchmarks-verification" aria-label="Permalink to &quot;Scripts, Benchmarks &amp; Verification&quot;">​</a></h1><p>The suite of testing and verification scripts in <code>scripts/</code> — what each does and how to run it.</p><p>All run from the repo root with <code>node scripts/&lt;name&gt;.mjs</code>. The common pattern: shim <code>globalThis.self/window</code>, load <code>public/swmm6wasm.js</code>, instantiate <code>swmm6wasm.wasm</code> in Node, and wrap the C API with <code>Module.cwrap</code>. Several spawn <code>server.py</code> + a Chrome instance via CDP.</p><h2 id="benchmarks-probes-engine-in-node" tabindex="-1">Benchmarks &amp; probes (engine in Node) <a class="header-anchor" href="#benchmarks-probes-engine-in-node" aria-label="Permalink to &quot;Benchmarks &amp; probes (engine in Node)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Purpose</th><th>Usage</th></tr></thead><tbody><tr><td><code>bench-1d-bellinge.mjs</code></td><td>Per-stride and per-window benchmark costs on Bellinge model; projects 48 h wall time</td><td>no args</td></tr><tr><td><code>bench-1d.mjs</code></td><td>Bare 1D stride benchmark; JSON output</td><td><code>node bench-1d.mjs &lt;inp&gt; [--wasm &lt;path&gt;] [--tag &lt;l&gt;] [--keep-vs]</code></td></tr><tr><td><code>probe-1d.mjs</code></td><td>Per-step junction head/depth dump (capped 80 steps)</td><td><code>node probe-1d.mjs &lt;inp&gt;</code></td></tr><tr><td><code>probe-1d-nan.mjs</code></td><td>Full 48 h 1D run scanning heads/depths/volumes for NaN/Inf anomalies</td><td><code>node probe-1d-nan.mjs [VS]</code></td></tr><tr><td><code>bench-wasm-threads.mjs</code></td><td><strong>Threaded-engine benchmark:</strong> runs <code>simWorker.js</code> in cross-origin-isolated Chrome at THREADS 1 vs N; reports wall time + bit-identical continuity</td><td><code>node bench-wasm-threads.mjs [--inp &lt;p&gt;] [--threads 1,4] [--minutes &lt;n&gt;]</code></td></tr></tbody></table><h2 id="chrome-cdp-end-to-end-harnesses-unit-tests" tabindex="-1">Chrome/CDP end-to-end harnesses &amp; unit tests <a class="header-anchor" href="#chrome-cdp-end-to-end-harnesses-unit-tests" aria-label="Permalink to &quot;Chrome/CDP end-to-end harnesses &amp; unit tests&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Purpose</th><th>Port</th><th>Usage</th></tr></thead><tbody><tr><td><code>test-network3d.mjs</code></td><td>Unit test suite for 3D network geometry (polygon generation, link paths, feature mapping)</td><td>—</td><td><code>npm run test:3d</code></td></tr><tr><td><code>verify-bellinge.mjs</code></td><td><strong>Automated verification gate:</strong> headless Chrome loads the app, loads Bellinge Web, executes the simulation via <code>simWorker.js</code>, and verifies output continuity</td><td>CDP 9222</td><td>no args; writes <code>scripts/verify-out/</code></td></tr><tr><td><code>verify-1d-split.mjs</code></td><td>Regression gate for the 1D simulation leg; verifies finite hydraulic heads</td><td>—</td><td><code>node verify-1d-split.mjs &lt;inp&gt; [--wasm &lt;p&gt;] [--tol &lt;%&gt;] [--hours &lt;n&gt;] [--json]</code></td></tr><tr><td><code>verify-lchar.mjs</code></td><td>Characteristic length verification</td><td>—</td><td><code>node verify-lchar.mjs &lt;inp&gt;</code></td></tr></tbody></table>',7)])])}const b=t(s,[["render",n]]);export{l as __pageData,b as default};
